/bin/bash -lc "rtk env PYTHONDONTWRITEBYTECODE=1 TMPDIR=/dev/shm python -m unittest discover -q -s artifacts/NC-020 -p test_benchmark.py
rtk env PYTHONDONTWRITEBYTECODE=1 TMPDIR=/dev/shm python -c 'import sys; sys.path.insert(0,\"artifacts/NC-020\"); import benchmark; 
try: benchmark.audit([])
except ValueError as e: print(type(e).__name__+\":\"+str(e))
else: raise SystemExit(\"audit([]) unexpectedly accepted\")'
rtk sha256sum artifacts/NC-020/codex_verifier_trace.jsonl artifacts/NC-020/codex_verifier_final.json artifacts/NC-020/codex_verifier_v2_trace.jsonl artifacts/NC-020/codex_verifier_v2_final.json artifacts/NC-020/benchmark.py artifacts/NC-001/canonical_isa.py artifacts/NC-019/semantic_objective.json artifacts/NC-020/equivalence_benchmark.jsonl
rtk rg -l 'current_unified_v3|checkpoint.*42|42.*checkpoint' artifacts/NC-005 artifacts/NC-006 | sort
rtk find artifacts/NC-005 artifacts/NC-006 -maxdepth 2 -type f | sort"

